// Bengali digit converter
function toBengali(n) {
    return String(n).replace(/[0-9]/g, function(d) { return '০১২৩৪৫৬৭৮৯'[+d]; });
}

$(document).ready(function() {

    // Count-up animation for hero stats
    var statsAnimated = false;
    var statsEl = document.querySelector('.hero-stats');
    if (statsEl) {
        var statsObserver = new IntersectionObserver(function(entries) {
            if (entries[0].isIntersecting && !statsAnimated) {
                statsAnimated = true;
                $('.stat-num[data-count]').each(function() {
                    var $el = $(this);
                    var target = +$el.data('count');
                    var suffix = $el.data('suffix') || '';
                    var duration = 1400;
                    var startTime = performance.now();
                    function step(now) {
                        var progress = Math.min((now - startTime) / duration, 1);
                        var eased = 1 - Math.pow(1 - progress, 3);
                        $el.text(toBengali(Math.round(eased * target)) + suffix);
                        if (progress < 1) requestAnimationFrame(step);
                    }
                    requestAnimationFrame(step);
                });
            }
        }, { threshold: 0.5 });
        statsObserver.observe(statsEl);
    }

    // Marquee - duplicate items for seamless loop
    var $track = $('.school-grid.marquee-track');
    if ($track.length) {
        var $clone = $track.children().clone(true);
        $track.append($clone);
    }

    // Smooth scroll
    $('a[href^="#"]').on('click', function(e) {
        var target = $(this.getAttribute('href'));
        if (target.length) { e.preventDefault(); $('html,body').animate({scrollTop: target.offset().top - 70}, 600); }
    });

    // Feature tabs
    $('.tab-btn').on('click', function() {
        var tab = $(this).data('tab');
        $('.tab-btn').removeClass('active');
        $(this).addClass('active');
        $('.feature-panel').removeClass('active');
        $('#tab-' + tab).addClass('active');
    });

    // FAQ categories
    $('.faq-cat-btn').on('click', function() {
        var cat = $(this).data('faqcat');
        $('.faq-cat-btn').removeClass('active');
        $(this).addClass('active');
        $('.faq-group').removeClass('active');
        $('#faq-' + cat).addClass('active');
        // reset all open items
        $('.faq-item').removeClass('open').find('.faq-a').hide();
    });

    // FAQ accordion
    $(document).on('click', '.faq-q', function() {
        var parent = $(this).parent('.faq-item');
        var answer = parent.find('.faq-a');
        var isOpen = parent.hasClass('open');
        parent.closest('.faq-group').find('.faq-item').removeClass('open').find('.faq-a').slideUp(200);
        if (!isOpen) { parent.addClass('open'); answer.slideDown(280); }
    });

    // Scroll animations
    var observer = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (entry.isIntersecting) {
                $(entry.target).addClass('visible');
            }
        });
    }, { threshold: 0.08 });
    $('.animate-on-scroll').each(function(i) {
        $(this).css('transition-delay', (i % 4 * 0.08) + 's');
        observer.observe(this);
    });

    // ── Preview Modal ──
    var previewModal = new bootstrap.Modal(document.getElementById('previewModal'));

    function renderPreview(key) {
        var info = pageInfo[key];
        if (!info) return;

        $('#previewModalLabel').html(
            '<i class="' + info.icon + ' me-2" style="color:' + info.color + '"></i>' + info.title
        );

        if (info.html) {
            $('#previewMainImg').html(info.html);
        } else {
            var $img = $('<img>')
                .attr('src', info.imgs[0])
                .attr('alt', info.title)
                .css({ width:'100%', borderRadius:'8px', border:'1px solid var(--border)', display:'block' });
            $('#previewMainImg').empty().append($img);
        }

        $('#previewThumbs').html('');
    }

    $(document).on('click', '.btn-preview', function() {
        var key = $(this).attr('data-key') || '';
        if (!key) return;
        renderPreview(key);
        previewModal.show();
    });

});
